const raw=$json.sync_context;
const ctx=typeof raw==='string'?JSON.parse(raw):raw;
if(!ctx || ctx.connector_key!=='airtable_primary' || ctx.connector_type!=='airtable') throw new Error('AIRTABLE_SYNC_CONTEXT_INVALID');
let gate=ctx.reliability_gate;
if(typeof gate==='string') gate=JSON.parse(gate);
const field=String($env.AIRTABLE_LAST_MODIFIED_FIELD??'').trim();
if(!/^[A-Za-z0-9 _-]{1,100}$/.test(field) || field.startsWith('CHANGE_ME')) throw new Error('AIRTABLE_LAST_MODIFIED_FIELD_INVALID');
const start=new Date(ctx.query_start_at).toISOString();
const end=new Date(ctx.query_end_at).toISOString();
const esc=s=>String(s).replace(/'/g,"\\'");
const formula="AND(IS_AFTER({"+field+"}, '"+esc(start)+"'), IS_BEFORE({"+field+"}, '"+esc(end)+"'))";
return {sync_context:ctx,should_sync:gate?.allowed===true,skip_reason:gate?.allowed===true?null:'RELIABILITY_CIRCUIT_OPEN',airtable_filter_formula:formula,last_modified_field:field};

const contextRaw=$('DB | Load Airtable Sync Context').first().json.sync_context;
const ctx=typeof contextRaw==='string'?JSON.parse(contextRaw):contextRaw;
const meta=$('CTX | Build Airtable Search').first().json;
const field=meta.last_modified_field;
const source=$input.all().map(x=>x.json??{}).filter(x=>String(x.id??'').trim()!=='');
if(source.length>2000) throw new Error('AIRTABLE_SYNC_RESULT_LIMIT_EXCEEDED');
const parse=v=>{if(v===null||v===undefined||v==='')return null;const d=new Date(String(v));return Number.isNaN(d.getTime())?null:d.toISOString();};
const queryStart=new Date(ctx.query_start_at).getTime();
const queryEnd=new Date(ctx.query_end_at).getTime();
const records=[];
let earliest=null;
for(const r of source){
  const id=String(r.id??'').trim();
  const updated=parse(r[field]);
  if(!id || id.length>200 || !updated) throw new Error('AIRTABLE_SOURCE_RECORD_INVALID');
  const ms=new Date(updated).getTime();
  if(earliest===null||ms<earliest) earliest=ms;
  const payload={...r};
  delete payload.id;
  records.push({source_record_id:id,source_payload:payload});
}
const watermark=records.length?new Date(Math.min(queryEnd,Math.max(queryStart,...source.map(r=>new Date(parse(r[field])).getTime())))).toISOString():new Date(queryEnd).toISOString();
return [{json:{connector_key:'airtable_primary',query_start_at:new Date(queryStart).toISOString(),query_end_at:new Date(queryEnd).toISOString(),watermark,source_count:records.length,record_count:records.length,rejected_count:0,records,event_id:'AIRTABLE-SYNC-'+String(queryEnd)}}];
